  ('77777777-0000-0000-0000-000000000001', '33333333-0000-0000-0000-000000000001', null, 'Lucknowi Chicken Dum Biryani', 'lucknowi-chicken-dum-biryani', 'Aged basmati, tender chicken, saffron milk and whole Awadhi spices; sealed handi dum cooking for fragrant, separate grains.', 'A freshly prepared Lucknowi Chicken Dum Biryani built around aged basmati, tender chicken, saffron milk and whole Awadhi spices. Preparation: sealed handi dum cooking for fragrant, separate grains. Finished with fried onions, mint and a squeeze of lime; served with cool boondi raita and mirchi ka salan.', 'menu-images/products/expansion/lucknowi-chicken-dum-biryani.jpg', 'menu-images/products/expansion/lucknowi-chicken-dum-biryani.jpg', 'NON_VEG', 'MILD', array['dairy', 'nuts']::text[], array['high-protein']::text[], 329, null, 10, '22222222-0000-0000-0000-000000000001', 30, 1, 790, false, false, true, false, false, 1000, 10, array['lucknowi', 'chicken', 'dum', 'biryani', 'aged', 'basmati', 'tender', 'saffron', 'milk', 'whole', 'awadhi', 'spices', 'non', 'veg', 'bites', 'box']::text[], 'Lucknowi Chicken Dum Biryani | Bites Box', 'Aged basmati, tender chicken, saffron milk and whole Awadhi spices. Prepared fresh to order in the Bites Box kitchen.'),
