  ('77777777-0000-0000-0000-000000000004', '33333333-0000-0000-0000-000000000001', null, 'Andhra Chilli Chicken Biryani', 'andhra-chilli-chicken-biryani', 'Tender chicken, fragrant rice and fiery Andhra red chilli; slow dum cooked with a bold chilli-forward masala.', 'A freshly prepared Andhra Chilli Chicken Biryani built around tender chicken, fragrant rice and fiery Andhra red chilli. Preparation: slow dum cooked with a bold chilli-forward masala. Finished with fried curry leaves and coriander; served with cool cucumber raita.', 'menu-images/products/expansion/andhra-chilli-chicken-biryani.jpg', 'menu-images/products/expansion/andhra-chilli-chicken-biryani.jpg', 'NON_VEG', 'EXTRA_HOT', array['dairy']::text[], array['high-protein']::text[], 339, null, 10, '22222222-0000-0000-0000-000000000001', 32, 1, 850, false, false, true, false, false, 1003, 10, array['andhra', 'chilli', 'chicken', 'biryani', 'tender', 'fragrant', 'rice', 'fiery', 'red', 'non', 'veg', 'bites', 'box']::text[], 'Andhra Chilli Chicken Biryani | Bites Box', 'Tender chicken, fragrant rice and fiery Andhra red chilli. Prepared fresh to order in the Bites Box kitchen.'),
  ('77777777-0000-0000-0000-000000000005', '33333333-0000-0000-0000-000000000001', null, 'Chicken Keema Biryani', 'chicken-keema-biryani', 'Fine chicken keema, aged basmati and warm whole spices; wok-seared keema layered through dum rice.', 'A freshly prepared Chicken Keema Biryani built around fine chicken keema, aged basmati and warm whole spices. Preparation: wok-seared keema layered through dum rice. Finished with mint, browned onions and lemon; served with plain raita.', 'menu-images/products/expansion/chicken-keema-biryani.jpg', 'menu-images/products/expansion/chicken-keema-biryani.jpg', 'NON_VEG', 'MEDIUM', array['dairy']::text[], array['high-protein']::text[], 299, null, 10, '22222222-0000-0000-0000-000000000001', 28, 1, 780, false, false, true, false, false, 1004, 10, array['chicken', 'keema', 'biryani', 'fine', 'aged', 'basmati', 'warm', 'whole', 'spices', 'non', 'veg', 'bites', 'box']::text[], 'Chicken Keema Biryani | Bites Box', 'Fine chicken keema, aged basmati and warm whole spices. Prepared fresh to order in the Bites Box kitchen.'),
  ('77777777-0000-0000-0000-000000000006', '33333333-0000-0000-0000-000000000001', null, 'Awadhi Mutton Yakhni Biryani', 'awadhi-mutton-yakhni-biryani', 'Slow-braised goat, aromatic yakhni stock and aged basmati; delicately layered and sealed for long dum cooking.', 'A freshly prepared Awadhi Mutton Yakhni Biryani built around slow-braised goat, aromatic yakhni stock and aged basmati. Preparation: delicately layered and sealed for long dum cooking. Finished with saffron, mint and crisp onions; served with lightly spiced raita.', 'menu-images/products/expansion/awadhi-mutton-yakhni-biryani.jpg', 'menu-images/products/expansion/awadhi-mutton-yakhni-biryani.jpg', 'NON_VEG', 'MILD', array['dairy']::text[], array['high-protein']::text[], 429, null, 10, '22222222-0000-0000-0000-000000000001', 40, 1, 920, false, false, true, false, false, 1005, 10, array['awadhi', 'mutton', 'yakhni', 'biryani', 'slow', 'braised', 'goat', 'aromatic', 'stock', 'aged', 'basmati', 'non', 'veg', 'bites', 'box']::text[], 'Awadhi Mutton Yakhni Biryani | Bites Box', 'Slow-braised goat, aromatic yakhni stock and aged basmati. Prepared fresh to order in the Bites Box kitchen.'),
  ('77777777-0000-0000-0000-000000000007', '33333333-0000-0000-0000-000000000001', null, 'Kolkata Mutton Biryani', 'kolkata-mutton-biryani', 'Soft goat pieces, fragrant rice and a slow-cooked potato; finished Kolkata style with gentle spice and long dum.', 'A freshly prepared Kolkata Mutton Biryani built around soft goat pieces, fragrant rice and a slow-cooked potato. Preparation: finished Kolkata style with gentle spice and long dum. Finished with golden onions and a boiled egg; served with cool cucumber raita.', 'menu-images/products/expansion/kolkata-mutton-biryani.jpg', 'menu-images/products/expansion/kolkata-mutton-biryani.jpg', 'NON_VEG', 'MILD', array['dairy']::text[], array['high-protein']::text[], 419, null, 10, '22222222-0000-0000-0000-000000000001', 40, 1, 910, false, false, true, false, false, 1006, 10, array['kolkata', 'mutton', 'biryani', 'soft', 'goat', 'pieces', 'fragrant', 'rice', 'slow', 'cooked', 'potato', 'non', 'veg', 'bites', 'box']::text[], 'Kolkata Mutton Biryani | Bites Box', 'Soft goat pieces, fragrant rice and a slow-cooked potato. Prepared fresh to order in the Bites Box kitchen.'),
