  ('77777777-0000-0000-0000-000000000009', '33333333-0000-0000-0000-000000000001', null, 'Paneer Tikka Biryani', 'paneer-tikka-biryani', 'Charred paneer tikka, saffron basmati and peppery masala; layered and sealed for gentle dum cooking.', 'A freshly prepared Paneer Tikka Biryani built around charred paneer tikka, saffron basmati and peppery masala. Preparation: layered and sealed for gentle dum cooking. Finished with mint, fried onions and toasted cashew; served with mint raita.', 'menu-images/products/expansion/paneer-tikka-biryani.jpg', 'menu-images/products/expansion/paneer-tikka-biryani.jpg', 'VEG', 'MEDIUM', array['dairy', 'nuts']::text[], array['vegetarian']::text[], 279, null, 10, '22222222-0000-0000-0000-000000000001', 26, 1, 730, true, false, true, true, false, 1008, 10, array['paneer', 'tikka', 'biryani', 'charred', 'saffron', 'basmati', 'peppery', 'masala', 'veg', 'bites', 'box']::text[], 'Paneer Tikka Biryani | Bites Box', 'Charred paneer tikka, saffron basmati and peppery masala. Prepared fresh to order in the Bites Box kitchen.'),
